const THIRD_STAR_SIGNATURE=['三番星の裁き',24,6,'0.4・0.9・1.4秒後、現在の照準へ長さ460・半幅18の光線。射線上の生存敵を手前から数え、3体目だけに各300%。光線の直接ダメージは手前2体と4体目以降には当たらず（属性反応は別）、3体未満では空振りする。各射撃で数え直すため、対象を倒すと奥の敵が次の対象になる。射線は壁で遮られる。移動と照準で敵を並べ、金色の印を狙う。範囲補正は線幅だけ。死亡・地域移動・壁越しの移動・1更新200超の瞬間移動で解除。再発動は置き換え。','M5 26H49M13 21V31M26 21V31M40 15L43 22L50 26L43 30L40 37L37 30L30 26L37 22Z'];
SIGNATURE_SKILLS.push(THIRD_STAR_SIGNATURE);Object.assign(GEM.crafted_11_7,{name:THIRD_STAR_SIGNATURE[0],cost:24,cool:6,desc:THIRD_STAR_SIGNATURE[3],ability:null,signature:127,tags:['spell','area']});
SIGNATURE_AUDIO.push(['thirdstar',710,.25]);SKILL_AUDIO_FAMILIES.electric.add('thirdstar');
function thirdStarValid(s){return !s.finished&&s.owner===p&&s.world===dungeon&&!dead&&p?.hp>0;}
function thirdStarTargets(ray,radius){const dx=Math.cos(ray.angle),dy=Math.sin(ray.angle);return enemies.filter(e=>echoVolleyTouches(ray,e,radius)).sort((a,b)=>((a.x-b.x)*dx+(a.y-b.y)*dy)).slice(0,3);}
const thirdStarCastBase=castCraftedSkill;castCraftedSkill=(build,...args)=>{const result=thirdStarCastBase(build,...args);if(GEM[build.type]?.signature!==127)return result;const s=signatureSpells.at(-1);if(s?.mode!==127)return result;signatureSpells=signatureSpells.filter(v=>v.mode!==127||v===s);Object.assign(s,{owner:p,world:dungeon,finished:false,target:null,heading:s.angle,ticks:0,rays:[],last:{x:p.x,y:p.y}});return result;};
const thirdStarStepBase=stepSignature;stepSignature=(s,dt)=>{
 if(s.mode!==127)return thirdStarStepBase(s,dt);if(!thirdStarValid(s)){s.finished=true;return false;}if(paused||!Number.isFinite(dt)||dt<=0)return true;
 if(dist(p,s.last)>200||!lineClear(s.last,p)){s.finished=true;return false;}s.last={x:p.x,y:p.y};s.time+=dt;const aim=unproject(mouse.x,mouse.y);if(dist(p,aim)>5)s.heading=Math.atan2(aim.y-p.y,aim.x-p.x);
 while(s.ticks<3&&s.time+1e-8>=.4+s.ticks*.5){if(!thirdStarValid(s))return false;const ray={x:p.x,y:p.y,angle:s.heading,until:.6+s.ticks*.5},targets=thirdStarTargets(ray,s.build.radius),target=targets[2];ray.end=target?{x:target.x,y:target.y}:echoVolleyEnd(ray);ray.hit=!!target;s.rays.push(ray);s.ticks++;if(target){spellHit(target,s.damage*3,s.build);if(!thirdStarValid(s))return false;}playSignatureAudio(127,true,ray.x,ray.y);}
 if(s.time+1e-8>=1.65){s.finished=true;return false;}return true;
};
function thirdStarPreview(s){const aim=unproject(mouse.x,mouse.y),ray={x:p.x,y:p.y,angle:dist(p,aim)>5?Math.atan2(aim.y-p.y,aim.x-p.x):s.heading};return {ray,targets:thirdStarTargets(ray,s.build.radius)};}
const thirdStarPaintBase=paintSignatureSpells;paintSignatureSpells=()=>{thirdStarPaintBase();for(const s of signatureRenderList(127)){if(!thirdStarValid(s))continue;const color=ELEMENTS[s.build.elements[0]].color;for(const ray of s.rays){if(s.time>=ray.until||!lineClear(ray,ray.end))continue;paintLinkLine(ray,ray.end,ray.hit?color:'#667a86',ray.hit?7:1);if(ray.hit){paintLinkLine(ray,ray.end,'#fff0ad',2);groundRing(ray.end.x,ray.end.y,20,'#fff0ad',3);}}if(s.ticks<3){const v=thirdStarPreview(s);paintLinkLine(v.ray,v.targets[2]||echoVolleyEnd(v.ray),'#94a5af',1);for(let i=0;i<v.targets.length;i++){const e=v.targets[i];groundRing(e.x,e.y,i===2?30:18,i===2?'#ffe39b':'#8da9b4',i===2?3:1);const q=project(e.x,e.y);ctx.save();ctx.fillStyle=i===2?'#ffe39b':'#b4c6ce';ctx.font='bold 14px sans-serif';ctx.textAlign='center';ctx.fillText(i===2?'★':String(i+1),q.x,q.y-74);ctx.restore();}}}};
const thirdStarStatusBase=controlSkillStatus;controlSkillStatus=s=>s.mode===127?{label:'三番星 '+s.ticks+'/3射 · '+(thirdStarPreview(s).targets.length===3?'3体目を捕捉':'射線に3体必要'),value:s.ticks/3,waiting:s.ticks<3}:thirdStarStatusBase(s);
